"use client"

import { useState } from "react"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Textarea } from "@/components/ui/textarea"
import { Label } from "@/components/ui/label"

export default function CreatePostForm() {
  // State for form fields
  const [title, setTitle] = useState("")
  const [content, setContent] = useState("")

  // State for form submission
  const [isSubmitting, setIsSubmitting] = useState(false)

  // Check if both fields have content to enable the Publish button
  const isFormValid = title.trim() !== "" && content.trim() !== ""

  // Handle form submission
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    if (!isFormValid) return

    setIsSubmitting(true)

    try {
      // Here you would typically send the data to your API
      console.log("Submitting post:", { title, content })

      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 1000))

      // Reset form after successful submission
      setTitle("")
      setContent("")

      alert("Post published successfully!")
    } catch (error) {
      console.error("Error publishing post:", error)
      alert("Failed to publish post. Please try again.")
    } finally {
      setIsSubmitting(false)
    }
  }

  return (
    <div className="max-w-2xl mx-auto p-6 space-y-6">
      <div className="space-y-2">
        <h1 className="text-3xl font-bold tracking-tight">Create New Post</h1>
        <p className="text-muted-foreground">
          Fill in the title and content below to create a new post.
        </p>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        {/* Title Field */}
        <div className="space-y-2">
          <Label htmlFor="title">Title</Label>
          <Input
            id="title"
            type="text"
            placeholder="Enter your post title..."
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            className="w-full"
          />
          <p className="text-sm text-muted-foreground">
            {title.length}/100 characters
          </p>
        </div>

        {/* Content Field */}
        <div className="space-y-2">
          <Label htmlFor="content">Content</Label>
          <Textarea
            id="content"
            placeholder="Write your post content here..."
            value={content}
            onChange={(e) => setContent(e.target.value)}
            rows={8}
            className="w-full resize-none"
          />
          <p className="text-sm text-muted-foreground">
            {content.length}/5000 characters
          </p>
        </div>

        {/* Form Validation Status */}
        <div className="text-sm text-muted-foreground">
          {!isFormValid && (
            <p>
              ⚠️ Please fill in both the title and content to publish your post.
            </p>
          )}
          {isFormValid && (
            <p className="text-green-600">
              ✓ Ready to publish!
            </p>
          )}
        </div>

        {/* Action Buttons */}
        <div className="flex items-center justify-end space-x-4 pt-4 border-t">
          <Button
            type="button"
            variant="outline"
            onClick={() => {
              setTitle("")
              setContent("")
            }}
            disabled={isSubmitting}
          >
            Clear
          </Button>

          <Button
            type="submit"
            disabled={!isFormValid || isSubmitting}
            className="min-w-[100px]"
          >
            {isSubmitting ? (
              <>
                <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white mr-2"></div>
                Publishing...
              </>
            ) : (
              "Publish"
            )}
          </Button>
        </div>
      </form>

      {/* Live Preview (Optional) */}
      <div className="mt-8 p-6 border rounded-lg bg-muted/50">
        <h2 className="text-lg font-semibold mb-4">Preview</h2>
        <div className="space-y-4">
          {title && (
            <div>
              <h3 className="text-xl font-bold">{title}</h3>
            </div>
          )}
          {content && (
            <div className="whitespace-pre-wrap text-muted-foreground">
              {content}
            </div>
          )}
          {!title && !content && (
            <p className="text-muted-foreground italic">
              Your post preview will appear here...
            </p>
          )}
        </div>
      </div>
    </div>
  )
}

